   return (
    <table className={styles.registry_table}>
      <tbody>
        {users ? (
          users.map(user => (
            <tr key={user.id}>
              <td>{user.name}</td>
              <td>{user.email}</td>
              <td>3 of 3</td>
            </tr>
          ))
        ) : (
          <tr>
            <td colSpan="3">Betöltés...</td>
          </tr>
        )}
      </tbody>
    </table>
  );
}
